model:
rachana: 1
sutra: oecd-country
version: 1
description: 
match: { kind: oecd-country, priority: 10 }
title: { pill: "Public sector · OECD country", id: "$.COUNTRY_ID", with: "$.COUNTRY_NAME" }
strip:
  - { label: "Leading indicator", bind: "$.LEADING_INDICATOR", fmt: "amount2" }
  - { label: "Unemployment, %", bind: "$.UNEMPLOYMENT", fmt: "price2" }
  - { label: "Inflation, %", bind: "$.INFLATION", fmt: "price2", emphasis: true }
  - { label: "GDP growth, % q/q", bind: "$.GDP_GROWTH", fmt: "price2" }
  - { label: "Inflation period", bind: "$.INFLATION_PERIOD" }
panels:
  - id: measures
    kind: table
    title: "Measures, latest period (a row opens its history)"
    key: "F2"
    code: "MEAS"
    rows: "$.MEASURES"
    search: false
    columns:
      - { label: "Measure", bind: "link(@.OECD_SERIES, 'oecd-series', @.TITLE)" }
      - { label: "Latest", bind: "@.LATEST", fmt: "amount2" }
      - { label: "Unit", bind: "@.UNIT" }
      - { label: "Period", bind: "@.PERIOD" }
      - { label: "Change", bind: "@.CHANGE", fmt: "signed2" }
  - id: members
    kind: map
    title: "Consumer price inflation by member, % (a member opens its page)"
    key: "F3"
    height: 11
    phone: { tier: "glance", from: "fragment", rows: 5 }
    highlight: "$.ISO3"
    link: { kind: "oecd-country", id: "OECD-{iso3}" }
    shade: { kind: "oecd-country", field: "$.INFLATION", by: "$.ISO3", fmt: "price2", label: "Inflation, %" }
  - id: source
    kind: kv
    title: "Data source and licence"
    area: right
    phone: { tier: "must", from: "fragment" }
    rows: "$.PROVENANCE"
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
    phone: { tier: "more", from: "fragment" }
keys: { F9: "raw" }
